	});
});

// ---------------------------------------------------------------------------
// startGatewayCron end-to-end (stub session factory)
// ---------------------------------------------------------------------------

describe("startGatewayCron", () => {
	function stubSessionFactory(text: string, onPrompt?: () => void, onShutdown?: (event: unknown) => void) {
		return async () => ({
			prompt: async () => {
				onPrompt?.();
			},
			abort: async () => {},
			subscribe: () => () => {},
			state: {
				messages: [
					{
						role: "assistant",
						content: [{ type: "text", text }],
						stopReason: "stop",
					},
				],
			},
			extensionRunner: {
				hasHandlers: () => true,
				emit: async (event: unknown) => onShutdown?.(event),
			},
			dispose: () => {},
		});
	}

	it("fires a due job, delivers wrapped content, advances job state; stop() halts", async () => {
		const adapter = new FakeAdapter("telegram");
		const runAt = new Date(Date.now() + 700).toISOString();
		const job = await createJob({
			prompt: "report status",
			schedule: runAt,
			name: "e2ejob",
			deliver: "telegram:123",
			origin: { platform: "telegram", chatId: "123" },
		});

		let guardSeenDuringPrompt = false;
		const shutdownEvents: unknown[] = [];
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig((c) => {
				c.telegram.homeChannel = "123";
			}),
			intervalMs: 100,
			sessionFactory: stubSessionFactory(
				"all green",
				() => {
					guardSeenDuringPrompt = isCronFire();
				},
				(event) => shutdownEvents.push(event),
			),
		});
		stoppers.push(cron.stop);

		const deadline = Date.now() + 5000;
		while (adapter.sent.length === 0 && Date.now() < deadline) {
			await new Promise((resolve) => setTimeout(resolve, 50));
		}
		expect(adapter.sent).toHaveLength(1);
		expect(adapter.sent[0].chatId).toBe("123");
		expect(adapter.sent[0].text).toBe("☾ Cron: e2ejob\n———\nall green");
		expect(guardSeenDuringPrompt).toBe(true);
		expect(shutdownEvents).toEqual([{ type: "session_shutdown", reason: "quit" }]);

		const after = getJob(job.id);
		expect(after.state).toBe("completed"); // one-shot fired
		expect(after.lastStatus).toBe("ok");

		cron.stop();
		const sendsAfterStop = adapter.sent.length;
		await new Promise((resolve) => setTimeout(resolve, 300));
		expect(adapter.sent).toHaveLength(sendsAfterStop);
	});

	it("replaces the global @lunr/cron-delivery bridge with the platform deliverer", async () => {
		const adapter = new FakeAdapter("telegram");
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig(),
			intervalMs: 60_000,
			sessionFactory: stubSessionFactory("unused"),
		});
		stoppers.push(cron.stop);

		const bridge = (globalThis as Record<symbol, unknown>)[Symbol.for("@lunr/cron-delivery")] as (
			job: CronJob,
			content: string,
		) => Promise<string | null>;
		expect(bridge).toBeTypeOf("function");
		const err = await bridge(
			fakeJob({
				deliver: "telegram:321",
				name: "bridgejob",
				origin: { platform: "telegram", chatId: "321" },
			}),
			"via bridge",
		);
		expect(err).toBeNull();
		expect(adapter.sent[0].chatId).toBe("321");
		expect(adapter.sent[0].text).toBe("☾ Cron: bridgejob\n———\nvia bridge");
	});

	it("rejects an explicit deliver target not in the allowlist", async () => {
		const adapter = new FakeAdapter("telegram");
		const cfg = makeConfig((c) => {
			c.telegram.homeChannel = "homeChat";
			c.telegram.allowedChats = ["allowed1"];
		});
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg,
			intervalMs: 60_000,
			sessionFactory: stubSessionFactory("unused"),
		});
		stoppers.push(cron.stop);

		await expect(
			createJob({
				prompt: "p",
				schedule: "30m",
				deliver: "telegram:attackerChat",
				origin: { platform: "telegram", chatId: "originChat" },
			}),
		).rejects.toThrow(/not an allowed chat/);

		const allowedExplicit = await createJob({
			prompt: "p",
			schedule: "30m",
			deliver: "telegram:allowed1",
			origin: { platform: "telegram", chatId: "originChat" },
		});
		expect(allowedExplicit.deliver).toBe("telegram:allowed1");
	});

	it("rejects a bare platform deliver when no homeChannel is configured", async () => {
		const adapter = new FakeAdapter("telegram");
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig(),
			intervalMs: 60_000,
			sessionFactory: stubSessionFactory("unused"),
		});
		stoppers.push(cron.stop);

		await expect(createJob({ prompt: "p", schedule: "30m", deliver: "telegram" })).rejects.toThrow(/no homeChannel/);
	});

	it("rejects telegram/discord deliver targets when chat-platforms is disabled", async () => {
		saveInstallFeatures({
			schemaVersion: 1,
			installerVersion: "0.1.0",
			installMethod: "binary",
			installedAt: "2026-01-01T00:00:00.000Z",
			updatedAt: "2026-01-01T00:00:00.000Z",
			features: { "chat-platforms": { enabled: false, options: {} } },
		});
		await expect(createJob({ prompt: "p", schedule: "30m", deliver: "telegram:123" })).rejects.toThrow(
			/lunr features enable chat-platforms/,
		);
	});

	it("allows deliver='origin' for a job with an origin", async () => {
		const adapter = new FakeAdapter("telegram");
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig(),
			intervalMs: 60_000,
			sessionFactory: stubSessionFactory("unused"),
		});
		stoppers.push(cron.stop);

		const job = await createJob({
			prompt: "p",
			schedule: "30m",
			deliver: "origin",
			origin: { platform: "telegram", chatId: "chat1" },
		});
		expect(job.deliver).toBe("origin");
	});
});

// ---------------------------------------------------------------------------
// startGatewayCron fallback models (settings cronFallbackModels / seam)
// ---------------------------------------------------------------------------

describe("startGatewayCron fallback models", () => {
	function makeSession(text: string, onPrompt?: () => Promise<void> | void) {
		return {
			prompt: async () => {
				await onPrompt?.();
			},
			abort: async () => {},
			subscribe: () => () => {},
			state: {
				messages: [{ role: "assistant", content: [{ type: "text", text }], stopReason: "stop" }],
			},
			dispose: () => {},
		};
	}

	async function waitFor(cond: () => boolean, ms = 5000): Promise<void> {
		const deadline = Date.now() + ms;
		while (!cond() && Date.now() < deadline) {
			await new Promise((resolve) => setTimeout(resolve, 50));
		}
	}

	it("falls back to the configured model when the default attempt fails", async () => {
		const adapter = new FakeAdapter("telegram");
		const seen: string[] = [];
		const job = await createJob({
			prompt: "p",
			schedule: new Date(Date.now() + 700).toISOString(),
			name: "fallbackjob",
			deliver: "telegram:123",
			origin: { platform: "telegram", chatId: "123" },
		});
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig(),
			intervalMs: 100,
			fallbackModels: [{ provider: "ollama-cloud", modelId: "glm-5.2" }],
			sessionFactory: async (_job, modelOverride) => {
				seen.push(modelOverride ? `${modelOverride.provider}/${modelOverride.modelId}` : "default");
				return makeSession("fallback result", () => {
					if (!modelOverride) throw new Error("rate limited");
				});
			},
		});
		stoppers.push(cron.stop);

		await waitFor(() => adapter.sent.length > 0);
		expect(seen).toEqual(["default", "ollama-cloud/glm-5.2"]);
		expect(adapter.sent[0].text).toBe(
			"☾ Cron: fallbackjob\n———\n[fell back to ollama-cloud/glm-5.2]\nfallback result",
		);
		expect(getJob(job.id).lastStatus).toBe("ok");
	});

	it("marks the job errored with every attempt listed when all candidates fail", async () => {
		const adapter = new FakeAdapter("telegram");
		const job = await createJob({
			prompt: "p",
			schedule: new Date(Date.now() + 700).toISOString(),
			name: "allfail",
			deliver: "telegram:123",
			origin: { platform: "telegram", chatId: "123" },
		});
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig(),
			intervalMs: 100,
			fallbackModels: [{ provider: "ollama-cloud", modelId: "glm-5.2" }],
			sessionFactory: async (_job, modelOverride) => {
				throw new Error(modelOverride ? "fallback down" : "primary down");
			},
		});
		stoppers.push(cron.stop);

		await waitFor(() => adapter.sent.length > 0);
		const after = getJob(job.id);
		expect(after.lastStatus).toBe("error");
		expect(after.lastError).toContain("default model: primary down");
		expect(after.lastError).toContain("ollama-cloud/glm-5.2: fallback down");
		// The failure notice exceeds the fake adapter's 100-char chunk size.
		expect(adapter.sent.map((m) => m.text).join("")).toContain("Cron job 'allfail' failed:");
	});

	it("runs a single attempt when no fallback models are configured", async () => {
		const adapter = new FakeAdapter("telegram");
		const seen: string[] = [];
		await createJob({
			prompt: "p",
			schedule: new Date(Date.now() + 700).toISOString(),
			name: "nofallback",
			deliver: "telegram:123",
			origin: { platform: "telegram", chatId: "123" },
		});
		const cron = startGatewayCron({
			adapters: new Map([["telegram", adapter]]),
			cfg: makeConfig(),
			intervalMs: 100,
			fallbackModels: [],
			sessionFactory: async (_job, modelOverride) => {
				seen.push(modelOverride ? "override" : "default");
				return makeSession("solo", () => {
					throw new Error("boom");
				});
			},
		});
		stoppers.push(cron.stop);

		await waitFor(() => adapter.sent.length > 0);
		expect(seen).toEqual(["default"]);
		expect(adapter.sent[0].text).toContain("Cron job 'nofallback' failed:");
	});
});

